// Leaves the Android window without a background. The stage paints the page's
// own ground over the whole panel, so a window background under it is one more
// full-screen fill the GPU blends on every frame and nobody sees. A config
// plugin because clients/tv-native/android is generated by `expo prebuild`.

import type { ConfigPlugin } from 'expo/config-plugins';
import { AndroidConfig, createRunOncePlugin, withAndroidStyles } from 'expo/config-plugins';

const withNoWindowBackground: ConfigPlugin = (config) =>
  withAndroidStyles(config, (cfg) => {
    cfg.modResults = AndroidConfig.Styles.assignStylesValue(cfg.modResults, {
      add: true,
      parent: AndroidConfig.Styles.getAppThemeGroup(),
      name: 'android:windowBackground',
      value: '@null',
    });
    return cfg;
  });

export default createRunOncePlugin(withNoWindowBackground, 'kroma-no-window-background', '1.0.0');
